import itertools, json, sys

L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}

# Pre‑compute all valid triples (a,b,c) with a+b=c
triples = []
for c in L:
    for a in L:
        if a >= c:
            continue
        b = c - a
        if b in L and b != a:
            triple = tuple(sorted((a, b, c)))
            triples.append(triple)
# Remove duplicates
triples = list({t for t in triples})

# Backtrack to select 15 disjoint triples covering all numbers
solution = []
used = set()

def backtrack(start):
    if len(solution) == 15:
        return True
    for i in range(start, len(triples)):
        a, b, c = triples[i]
        if a in used or b in used or c in used:
            continue
        # choose
        solution.append((a, b, c))
        used.update([a, b, c])
        if backtrack(i + 1):
            return True
        # undo
        solution.pop()
        used.difference_update([a, b, c])
    return False

found = backtrack(0)

if not found:
    witness = {"polarity": "negative", "evidence": {"path": "execution://witness"}, "basis": "search", "search_exhausted": true, "nodes_explored": null, "method": "backtrack"}
else:
    # format result as list of triples
    triples_result = [list(t) for t in solution]
    witness = {"polarity": "positive", "evidence": {"path": "execution://witness"}, "data": {"partition": triples_result}}

print(f"WITNESS: {json.dumps(witness)}")

L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}
solution = None

def backtrack(available, triples):
    global solution
    if solution is not None:
        return
    if not available:
        solution = triples.copy()
        return
    a = min(available)
    for b in available:
        if b == a:
            continue
        c = a + b
        if c in available and c != a and c != b:
            new_avail = set(available)
            new_avail.remove(a)
            new_avail.remove(b)
            new_avail.remove(c)
            triples.append((a, b, c))
            backtrack(new_avail, triples)
            triples.pop()
            if solution:
                return

backtrack(set(L), [])
import json, sys
if solution:
    print("WITNESS: " + json.dumps({"polarity": "positive", "evidence": {"path": "execution://witness"}, "data": {"partition": solution}}))
else:
    print("WITNESS: " + json.dumps({"polarity": "negative", "evidence": {"path": "execution://witness"}, "basis": "search", "search_exhausted": True}))
